insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-salatka-sledziowa', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-salatka-sledziowa/217de80a-a53b-4bc0-be52-f8f5b426a592.webp', 30, 15, 6, null, null, '{}'::jsonb, '', array['post-wigilia', 'post-polenladen', 'post-ersatzprodukte-de']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-salatka-sledziowa', 'de', 'Sałatka śledziowa', 'salatka-sledziowa', 'Cremiger Heringssalat mit Mayonnaise, Zwiebel und Apfel, ein fester Buffet- und Wigilia-Klassiker in der polnischen Küche.', '[{"text":"Matjes oder eingelegte Heringfilets abtropfen lassen und in mundgerechte Würfel schneiden. Zwiebel fein würfeln, wer die Schärfe mildern will, übergießt sie kurz mit heißem Wasser. Apfel schälen und würfeln, hartgekochte Eier und Gewürzgurken ebenfalls würfeln.","tip":"Das ist ein Mayo-Salat mit Hering, keine reinen Filets in Öl wie der [Śledź w oleju](/de/rezepte/sledz) und kein Gemüse-Mayo-Salat ohne Fisch wie die [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa)."},{"text":"Hering, Zwiebel, Apfel, Ei und Gurke in einer Schüssel vermengen. Mayonnaise, optional etwas Śmietana, unterheben, bis alles cremig gebunden ist und nichts mehr schwimmt. Mit Salz, Pfeffer und einer Prise Zucker abschmecken.","tip":"Gute Filets und Mayonnaise findest du oft im [Polenladen](/de/blog/polenladen-einkaufen), Alternativen beschreibt der Beitrag zu [Ersatzprodukten DE](/de/blog/ersatzprodukte-de)."},{"text":"Mindestens 1 bis 2 Stunden kalt durchziehen lassen, damit sich die Aromen verbinden. Vor dem Servieren noch einmal umrühren und nachwürzen, die Cremigkeit sollte dabei sichtbar bleiben.","tip":"Ihren Menüplatz bei der Wigilia beschreibt der [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan), der Speiseplan bleibt der Menü-Rahmen, hier geht es nur um das Rezept."},{"text":"Kalt in einer Schüssel servieren, optional mit etwas Schnittlauch. Auf dem Tisch steht sie oft neben Öl-Hering, der Fokus bleibt aber dieser Mayo-Salat. Wegen der Mayonnaise die Sałatka bis kurz vor dem Servieren gekühlt halten.","tip":"Die Öl-Linie bleibt beim [Śledź](/de/rezepte/sledz), Festgemüse mit Mayo bei der [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa)."}]'::jsonb, 'Sałatka śledziowa, cremig durch Mayonnaise, mit Zwiebel und Apfel, ein kalter Salat für Buffet und Wigilia. Hering ist in Polen seit dem Mittelalter die Fastenspeise schlechthin: Als kaltblütiges Tier durfte er an den zahlreichen Fasttagen des Kirchenjahres gegessen werden, während Fleisch verboten war, und war zugleich, in Salzlake konserviert, das ganze Jahr über verfügbar und für arme wie reiche Haushalte erschwinglich. Sałatka śledziowa ist die cremige, spätere Weiterentwicklung dieser Tradition: abgetropfte Filets, gebunden mit Mayonnaise statt nur mit Öl, ergänzt um Zwiebel, Apfel, Ei und Gurke, oft neben dem klassischen [Śledź w oleju](/de/rezepte/sledz) auf dem Wigilia-Tisch. [Śledź w oleju](/de/rezepte/sledz) bleibt bei kalten Filets mit Zwiebel und Öl, [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa) beim Gemüse-Mayo-Salat ohne Hering als Kern. Am [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan) stehen beide Hering-Formen oft nebeneinander, weil die Fastentradition eine Vielfalt an Fischgerichten hervorgebracht hat, nicht nur eine.

## Einkaufen und kochen

Nimm Hering- oder Matjesfilets, gute Mayonnaise und optional etwas Śmietana, dazu Zwiebel, einen säuerlichen Apfel, hartgekochte Eier, Gewürz- oder Salzgurken sowie Salz, Pfeffer und eine Prise Zucker, Schnittlauch zum Schluss. Filets und oft bessere Mayonnaise findest du im [Polenladen](/de/blog/polenladen-einkaufen). Das ist bewusst kein klarer [Śledź w oleju](/de/rezepte/sledz) und kein Gemüsesalat wie die [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa), hier trägt der Hering die Mayo-Schüssel.

Filets gründlich abtropfen lassen, denn zu viel Lake macht den Salat wässrig statt cremig. Wer die Schärfe der Zwiebel mildern möchte, blanchiert sie kurz. Alles würfeln, dann Mayonnaise, mit oder ohne Śmietana, unterheben, bis die Masse cremig gebunden ist und nicht flüssig wirkt. Mindestens ein bis zwei Stunden kalt durchziehen lassen, denn zu wenig Mayonnaise lässt den Salat bröckeln, zu viel erschlägt den Hering-Charakter komplett.

In Deutschland rettet der Mayo-Heringssalat oft den zweiten Buffet-Slot, wenn Öl-Hering schon auf dem Tisch steht, zwei Gerichte, ein Fisch. Matjes aus dem Glas und gute Supermarkt-Mayonnaise sind in der Diaspora ganz ehrliche Zutaten. Im [Polenladen](/de/blog/polenladen-einkaufen) findest du die typischen Zutaten, Alternativen beschreibt [Ersatzprodukte DE](/de/blog/ersatzprodukte-de), zum Menü passt [Wigilia](/de/blog/wigilia-speiseplan).

## Am Tisch

Kalt in einer Schüssel servieren, oft mit Schnittlauch, zur Wigilia passt der [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan), am Sonntag der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch). Auf dem Tisch klar halten: Öl-Filets sind [Śledź](/de/rezepte/sledz), Mayo-Gemüse ohne Hering ist [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa). Am besten hält sie einen Tag gekühlt, vor dem Servieren noch einmal cremig nachrühren.

Wer die Sałatka śledziowa mit [Śledź w oleju](/de/rezepte/sledz) verwechselt, erwartet Filets in Öl statt einen Mayo-Salat, wer sie mit [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa) gleichsetzt, vermisst den Hering als eigentlichen Kern. Zu wässrig abgetropfte Filets und zu kurze Kühlzeit lassen den Salat flach schmecken statt cremig durchgezogen.

Mehr Apfel macht sie süßer, mehr Gurke säuerlicher, und mit etwas mehr Śmietana wird sie leichter. Die Öl-Linie bleibt beim [Śledź](/de/rezepte/sledz), das Festgemüse bei der [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa), zum Anlass passt der [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan), im Alltag der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch), zum Einkauf der [Polenladen](/de/blog/polenladen-einkaufen) und die [Ersatzprodukte DE](/de/blog/ersatzprodukte-de).', 'Sałatka śledziowa Rezept | Heringssalat Mayo | Alemniam', 'Sałatka śledziowa: cremiger Heringssalat mit Mayonnaise, deutlich anders als Śledź w oleju oder Sałatka jarzynowa.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-salatka-sledziowa', 'pl', 'Sałatka śledziowa', 'salatka-sledziowa', 'Kremowa sałatka śledziowa z majonezem, cebulą i jabłkiem, stały klasyk bufetu i wigilijnego stołu.', '[{"text":"Matjasy lub filety śledziowe odsącz i pokrój w kostkę. Cebulę drobno posiekaj, a jeśli chcesz zmniejszyć jej ostrość, krótko zalej wrzątkiem. Jabłko obierz i pokrój, jajka na twardo oraz ogórki kiszone lub konserwowe również pokrój w kostkę.","tip":"To sałatka majonezowa ze śledziem, nie same filety w oleju jak [śledź w oleju](/pl/rezepte/sledz) i nie warzywna sałatka bez ryby jak [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa)."},{"text":"Wymieszaj śledzia, cebulę, jabłko, jajko i ogórek w misce. Dodaj majonez, opcjonalnie odrobinę śmietany, i wmieszaj, aż masa będzie kremowa, a nie rzadka. Dopraw solą, pieprzem i szczyptą cukru.","tip":"Dobre filety i majonez często kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy), o zamiennikach pisze wpis o [zamiennikach składników](/pl/blog/zamienniki-skladnikow)."},{"text":"Chłodź co najmniej 1 do 2 godzin, żeby smaki się przegryzły. Przed podaniem wymieszaj i ewentualnie dopraw, kremowość powinna być dobrze widoczna.","tip":"Jej miejsce na Wigilii opisuje [menu wigilijne](/pl/blog/menu-wigilijne), plan zostaje ramą stołu, tu chodzi tylko o przepis."},{"text":"Podawaj na zimno, opcjonalnie ze szczypiorkiem. Na stole może stać obok śledzia w oleju, ale fokus zostaje przy tej majonezowej sałatce. Z powodu majonezu trzymaj ją w chłodzie do samego podania.","tip":"Linia olejowa zostaje przy [śledziu](/pl/rezepte/sledz), warzywa z majonezem przy [sałatce jarzynowej](/pl/rezepte/salatka-jarzynowa)."}]'::jsonb, 'Sałatka śledziowa, kremowa przez majonez, z cebulą i jabłkiem, zimna sałatka na bufet i Wigilię. Śledź jest w Polsce od średniowiecza rybą postną w czystej postaci: jako zwierzę zimnokrwiste mógł być jedzony w liczne dni postne roku liturgicznego, gdy mięso było zakazane, a solony był dostępny przez cały rok i osiągalny finansowo zarówno dla biednych, jak i bogatych domów. Sałatka śledziowa to kremowa, późniejsza wersja tej tradycji: odsączone filety związane majonezem, a nie tylko olejem, wzbogacone cebulą, jabłkiem, jajkiem i ogórkiem, często obok klasycznego [śledzia w oleju](/pl/rezepte/sledz) na wigilijnym stole. [Śledź w oleju](/pl/rezepte/sledz) zostaje przy zimnych filetach z cebulą i olejem, [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa) przy majonezowej sałatce warzywnej bez śledzia jako rdzenia. Przy [menu wigilijnym](/pl/blog/menu-wigilijne) obie formy śledzia bywają obok siebie, bo tradycja postna wykształciła wiele różnych dań rybnych, nie tylko jedno.

## Zakupy i gotowanie

Weź filety śledziowe lub matjasy, dobry majonez i opcjonalnie odrobinę śmietany, do tego cebulę, kwaskowe jabłko, jajka na twardo, ogórki kiszone lub konserwowe oraz sól, pieprz i szczyptę cukru, na koniec szczypiorek. Filety i często lepszy majonez kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy). To świadomie nie klarowny [śledź w oleju](/pl/rezepte/sledz) i nie warzywna [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa), tu śledź prowadzi miskę majonezową.

Filety dobrze odsącz, bo za dużo zalewy robi sałatkę wodnistą, nie kremową. Jeśli chcesz zmniejszyć ostrość cebuli, krótko ją zblanszuj. Wszystko pokrój w kostkę, potem wmieszaj majonez, ze śmietaną albo bez niej, do kremowego związania, bez rzadkości. Chłodź co najmniej godzinę do dwóch, bo za mało majonezu sprawia, że sałatka się kruszy, a za dużo całkowicie zabija charakter śledzia.

W Niemczech majonezowa sałatka śledziowa często ratuje drugi slot bufetowy, gdy śledź w oleju już stoi na stole, dwa dania, jedna ryba. Matjasy ze słoika i dobry majonez z marketu są w diasporze zupełnie uczciwym wyborem. W [sklepie polskim](/pl/blog/sklep-polski-zakupy) kupisz typowe składniki, zamienniki opisują [zamienniki składników](/pl/blog/zamienniki-skladnikow), do menu pasuje [menu wigilijne](/pl/blog/menu-wigilijne).

## Przy stole

Podawaj na zimno w misce, często ze szczypiorkiem, na Wigilię pasuje [menu wigilijne](/pl/blog/menu-wigilijne), w niedzielę [obiad niedzielny](/pl/blog/obiad-niedzielny). Na stole rozróżniaj: filety w oleju to [śledź](/pl/rezepte/sledz), warzywa z majonezem bez śledzia to [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa). Najlepiej trzyma dzień w chłodzie, przed podaniem wymieszaj ją jeszcze raz do kremowości.

Kto myli sałatkę śledziową ze [śledziem w oleju](/pl/rezepte/sledz), oczekuje filetów w oleju zamiast sałatki majonezowej, kto zrównuje ją z [sałatką jarzynową](/pl/rezepte/salatka-jarzynowa), traci śledzia jako właściwy rdzeń dania. Za wodniste filety i za krótkie chłodzenie sprawiają, że sałatka smakuje płasko, a nie kremowo przegryzła.

Więcej jabłka daje słodszy smak, więcej ogórka kwaśniejszy, a odrobina więcej śmietany robi sałatkę lżejszą. Linia olejowa zostaje przy [śledziu](/pl/rezepte/sledz), warzywa świąteczne przy [sałatce jarzynowej](/pl/rezepte/salatka-jarzynowa), do okazji pasuje [menu wigilijne](/pl/blog/menu-wigilijne), na co dzień [obiad niedzielny](/pl/blog/obiad-niedzielny), do zakupów [sklep polski](/pl/blog/sklep-polski-zakupy) i [zamienniki składników](/pl/blog/zamienniki-skladnikow).', 'Sałatka śledziowa przepis | Majonez cebula jabłko | Alemniam', 'Sałatka śledziowa: kremowa sałatka z majonezem, inna niż śledź w oleju czy sałatka jarzynowa.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
